javascript
// Test cases for get_welcome_message function
function get_welcome_message(username) {
    return `Welcome, ${username}!`;
}

console.log(get_welcome_message("Alice"));  // Expected output: "Welcome, Alice!"
console.log(get_welcome_message("Bob"));    // Expected output: "Welcome, Bob!"
console.log(get_welcome_message("Charlie"));// Expected output: "Welcome, Charlie!"

// Test with special characters
console.log(get_welcome_message("<script>alert('XSS')</script>"));
// Expected output: "Welcome, <script>alert('XSS')</script>!" 
// Note: This demonstrates that the function does not sanitize input, 
// but since it's just returning a string for rendering, proper escaping should be handled by the rendering engine.

// Test with empty username
console.log(get_welcome_message(""));        // Expected output: "Welcome, !"

javascript
function test_get_welcome_message() {
    const username = "test_user";
    const expected_output = `Welcome, ${username}!`;
    const actual_output = get_welcome_message(username);
    console.assert(actual_output === expected_output, 
                  `Expected output: "${expected_output}", but got "${actual_output}"`);
}
